mapper.select:
SELECT id, project_id, waste_type, quantity, unit, vehicle_plate, driver_name, destination, removal_date, remark, operator_id, is_deleted, created_at, updated_at
FROM t_construction_waste WHERE is_deleted = 0
AND project_id = #{projectId}
AND waste_type LIKE CONCAT('%', #{wasteType}, '%')
AND removal_date >= #{startDate}
AND removal_date <= #{endDate}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM t_construction_waste WHERE is_deleted = 0
AND project_id = #{projectId}
AND waste_type LIKE CONCAT('%', #{wasteType}, '%')
AND removal_date >= #{startDate}
AND removal_date <= #{endDate}
